<?php require_once __DIR__ . '/../config/db.php'; $message = ''; $isRegistered = isset($_GET['registered']); if (($_SERVER['REQUEST_METHOD'] ?? '') === 'POST') { verify_csrf(); $email = strtolower(trim($_POST['email'] ?? '')); $stmt = $pdo->prepare('SELECT id, name, password, role FROM users WHERE email = ?'); $stmt->execute([$email]); $user = $stmt->fetch(); if ($user && password_verify($_POST['password'] ?? '', $user['password'])) { session_regenerate_id(true); $_SESSION['user_id'] = (int) $user['id']; $_SESSION['name'] = $user['name']; $_SESSION['role'] = $user['role']; header('Location: ' . APP_BASE . '/products/'); exit; } $message = 'Invalid email or password.'; } ?> <!DOCTYPE html> <html lang="en"> <head> <meta charset="UTF-8"> <meta name="viewport" content="width=device-width, initial-scale=1"> <title>Sign In | Bake Me Happy</title> <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"> <style> *{box-sizing:border-box} body{ margin:0;min-height:100vh; background:url('https://images.unsplash.com/photo-1578985545062-69928b1d9587?w=1600&q=80') center/cover no-repeat fixed; display:grid;place-items:center;padding:20px; font-family:system-ui;position:relative;overflow:hidden; } body::before{content:'';position:fixed;inset:0;background:rgba(0,0,0,.25);z-index:0} /* --- WORDS ON THE PICTURE --- */ .brand{position:fixed;top:24px;left:28px;z-index:2;color:#fff;text-shadow:0 2px 12px rgba(0,0,0,.8);display:flex;align-items:center;gap:12px} .brand img{width:64px;height:64px;object-fit:contain;border-radius:50%} .brand small{display:block;font-weight:700;letter-spacing:.25em;font-size:.65rem;color:#ffcf9e} .brand b{font-size:1.15rem} .quote-left{position:fixed;left:28px;bottom:28px;z-index:2;color:#fff;max-width:320px;text-shadow:0 2px 12px rgba(0,0,0,.8)} .quote-left h2{font-size:2.1rem;line-height:1.05;font-weight:800;margin:0} .quote-left p{opacity:.9;margin:8px 0 0} .quote-right{position:fixed;right:28px;bottom:28px;z-